findings.suggestion:
if (inProgress) {
  throw new Error(
    `${sanitizeReason(inProgress)} is in session ${id}'s worktree git dir: a rebase, merge, ` +
      'cherry-pick or revert was left in progress there, or the session planted its state. ' +
      'Delete it without running git in that worktree (an abort or continue there runs the ' +
      "session's head-name and orig-head with your rights, and can move any branch, main " +
      'included), then re-run `pup land`. ' +
      LAND_UNTOUCHED,
  );
}
